package android.os;
public class ResultReceiver {public static final Creator CREATOR=new Creator(); public static final class Creator {public ResultReceiver createFromParcel(Parcel p){ResultReceiver target=p.receiver;return new ResultReceiver(null){@Override public void send(int c,Bundle b){target.send(c,b);}};}} public void writeToParcel(Parcel p,int flags){p.receiver=this;} private final Handler handler;public ResultReceiver(Handler h){handler=h;} protected void onReceiveResult(int code,Bundle data){} public void send(int code,Bundle data){handler.post(()->onReceiveResult(code,data));}}
